import math
g = hou.node('/obj/girl'); hc = hou.node('/obj/hand_contact')
cb = hou.node('/obj/butterfly/CTRL_body')

def ndc(cam, p, t=None):
    c = hou.node(cam)
    M = c.worldTransform() if t is None else c.worldTransformAtTime(t)
    q = hou.Vector3(p) * M.inverted()
    f = c.evalParm('focal'); ap = c.evalParm('aperture'); asp = c.evalParm('resy') / c.evalParm('resx')
    return (f * q[0] / (-q[2]) / ap, f * q[1] / (-q[2]) / (ap * asp), -q[2])

def in_frustum(cam, p, margin=0.0):
    x, y, d = ndc(cam, p)
    return d > 0 and abs(x) <= 0.5 - margin and abs(y) <= 0.5 - margin

def axes(M):
    return [hou.Vector3(list(hou.Vector4(a + [0]) * M)[:3]) for a in ([1, 0, 0], [0, 1, 0], [0, 0, 1])]

def nelder_mead(f, x0, step=5.0, iters=300, tol=1e-9):
    n = len(x0)
    pts = [list(x0)]
    for i in range(n):
        p = list(x0); p[i] += step; pts.append(p)
    vals = [f(p) for p in pts]
    for it in range(iters):
        order = sorted(range(n + 1), key=lambda i: vals[i])
        pts = [pts[i] for i in order]; vals = [vals[i] for i in order]
        if abs(vals[-1] - vals[0]) < tol: break
        cen = [sum(p[i] for p in pts[:-1]) / n for i in range(n)]
        xr = [cen[i] + (cen[i] - pts[-1][i]) for i in range(n)]; fr = f(xr)
        if fr < vals[0]:
            xe = [cen[i] + 2 * (cen[i] - pts[-1][i]) for i in range(n)]; fe = f(xe)
            if fe < fr: pts[-1], vals[-1] = xe, fe
            else: pts[-1], vals[-1] = xr, fr
        elif fr < vals[-2]:
            pts[-1], vals[-1] = xr, fr
        else:
            xc = [cen[i] + 0.5 * (pts[-1][i] - cen[i]) for i in range(n)]; fc = f(xc)
            if fc < vals[-1]: pts[-1], vals[-1] = xc, fc
            else:
                for j in range(1, n + 1):
                    pts[j] = [pts[0][i] + 0.5 * (pts[j][i] - pts[0][i]) for i in range(n)]
                    vals[j] = f(pts[j])
    return pts[0], vals[0]

# --- Butterfly / girl animation helpers (E3_TV_r2) ---
# Used by parameter expressions on /obj/butterfly/CTRL_body, CTRL_wing_L/R and /obj/girl head channels.
import math
import hou

CB = '/obj/butterfly/CTRL_body'
HC = '/obj/hand_contact'
NECK = '/obj/girl/ctrl_rig_bone_neck'
EYE_OFFSET = hou.Vector3(0.0, 0.176, 0.11)   # neck pivot -> eye centre (rest pose)
BOB_F1, BOB_F2, BOB_FX = 1.3, 2.1, 0.9        # Hz, vertical bobbing layer
HEAD_LAG = 4.0                                 # frames, head look-at lag (exp. weighted)


def _ev(name, f):
    return hou.node(CB).parm(name).evalAtFrame(f)


def hc_matrix(f):
    return hou.node(HC).worldTransformAtTime(hou.frameToTime(f))


def path_world(f):
    """Authored spline path (keys on path_t*) + low-amplitude vertical bobbing layer."""
    t = hou.frameToTime(f)
    p = hou.Vector3(_ev('path_tx', f), _ev('path_ty', f), _ev('path_tz', f))
    a = _ev('bob_amp', f) * _ev('bob_w', f)
    by = a * (math.sin(2 * math.pi * BOB_F1 * t) + 0.5 * math.sin(2 * math.pi * BOB_F2 * t + 1.0)) / 1.5
    bx = 0.35 * a * math.sin(2 * math.pi * BOB_FX * t + 0.4)
    return p + hou.Vector3(bx, by, 0.0)


def hand_target(f):
    """Hover/landing point: rel_t* keys expressed in hand_contact local space."""
    rel = hou.Vector3(_ev('rel_tx', f), _ev('rel_ty', f), _ev('rel_tz', f))
    return rel * hc_matrix(f)


def w_hand(f):
    return min(1.0, max(0.0, _ev('w_hand', f)))


def bf_pos(f=None):
    if f is None:
        f = hou.frame()
    w = w_hand(f)
    if w <= 0.0:
        return path_world(f)
    if w >= 1.0:
        return hand_target(f)
    return path_world(f) * (1.0 - w) + hand_target(f) * w


def _flight_quat(f):
    v = bf_pos(f + 0.5) - bf_pos(f - 0.5)
    if v.length() < 1e-5:
        v = bf_pos(f + 3) - bf_pos(f - 3)
    if v.length() < 1e-6:
        v = hou.Vector3(0, 0, 1)
    h = math.hypot(v[0], v[2])
    yaw = math.atan2(v[0], v[2]) if h > 1e-7 else 0.0
    pitch = max(-0.35, min(0.35, math.atan2(v[1], max(h, 1e-7))))
    z = hou.Vector3(math.sin(yaw) * math.cos(pitch), math.sin(pitch), math.cos(yaw) * math.cos(pitch))
    x = hou.Vector3(0, 1, 0).cross(z).normalized()
    y = z.cross(x).normalized()
    m3 = hou.Matrix3(((x[0], x[1], x[2]), (y[0], y[1], y[2]), (z[0], z[1], z[2])))
    return hou.Quaternion(m3)


def _hand_quat(f):
    m = hc_matrix(f)
    ax = [hou.Vector3(list(hou.Vector4(a + [0]) * m)[:3]).normalized() for a in ([1, 0, 0], [0, 1, 0], [0, 0, 1])]
    m3 = hou.Matrix3(tuple(tuple(a) for a in ax))
    return hou.Quaternion(m3)


def bf_rot(f=None):
    if f is None:
        f = hou.frame()
    w = w_hand(f)
    if w >= 1.0:
        q = _hand_quat(f)
    elif w <= 0.0:
        q = _flight_quat(f)
    else:
        q = _flight_quat(f).slerp(_hand_quat(f), w)
    return q.extractEulerRotates('xyz')


def flap_phase(f=None):
    """Integrated phase (degrees) of flap_freq (Hz) so frequency keys change speed without phase jumps."""
    if f is None:
        f = hou.frame()
    p = hou.node(CB).parm('flap_freq')
    ph = 0.0
    k = 1.0
    prev = p.evalAtFrame(1.0)
    while k + 1.0 <= f:
        cur = p.evalAtFrame(k + 1.0)
        ph += 0.5 * (prev + cur) / hou.fps()
        prev = cur
        k += 1.0
    if f > k:
        cur = p.evalAtFrame(f)
        ph += 0.5 * (prev + cur) * (f - k) / hou.fps()
    return 360.0 * ph


def eye_pos(f):
    return EYE_OFFSET * hou.node(NECK).worldTransformAtTime(hou.frameToTime(f)) - \
        hou.Vector3(0, 0, 0) * hou.Matrix4(1) if False else \
        hou.node(NECK).worldTransformAtTime(hou.frameToTime(f)).extractTranslates() + EYE_OFFSET


def look_angles(target, eye):
    d = target - eye
    h = math.hypot(d[0], d[2])
    yaw = math.degrees(math.atan2(d[0], d[2]))
    pitch = math.degrees(math.atan2(-d[1], max(h, 1e-6)))
    return max(-30.0, min(45.0, pitch)), max(-75.0, min(75.0, yaw))


def lagged_target(f):
    """Exponentially weighted history of the butterfly position (time lag ~HEAD_LAG frames)."""
    acc = hou.Vector3(0, 0, 0)
    ws = 0.0
    for k in range(0, 13):
        w = math.exp(-k / HEAD_LAG)
        acc += bf_pos(max(1.0, f - k)) * w
        ws += w
    return acc / ws


def head_look(axis, f=None):
    """axis 0 -> headrotatex (pitch, + = down), 1 -> headrotatey (yaw, + = towards +X)."""
    if f is None:
        f = hou.frame()
    pitch, yaw = look_angles(lagged_target(f), eye_pos(f))
    return pitch if axis == 0 else yaw

