# --- Butterfly / girl animation helpers (E3_TV_r2_v1) ---
# Used by parameter expressions on /obj/butterfly/CTRL_body, CTRL_wing_L/R and /obj/girl head channels.
#
# CTRL_body tx/ty/tz keys are positions expressed in hand_contact space (the hand_contact frame of the
# presented-hand pose, REF_F).  Each key segment evaluates  bezier() + bf_delta(axis)  where the layer adds:
#   * hand_contact constraint: w_hand blends the frozen reference frame (=world flight) with the live
#     hand_contact world transform (=constraint), so the same keys are hand-relative hover/landing keys;
#   * a low-amplitude vertical bobbing layer weighted by bob_w.
import math
import hou

CB = '/obj/butterfly/CTRL_body'
HC = '/obj/hand_contact'
NECK = '/obj/girl/ctrl_rig_bone_neck'
EYE_OFFSET = hou.Vector3(0.0, 0.10, 0.0)      # neck pivot -> rig_bone_head origin (look-at origin)
BOB_F1, BOB_F2, BOB_FX = 1.3, 2.1, 0.9        # Hz, vertical bobbing layer
HEAD_LAG = 4.0                                 # frames, head look-at lag (exp. weighted)
REF_F = 100.0                                  # hand_contact reference frame (hand static F96-F240)


def _ev(name, f):
    return hou.node(CB).parm(name).evalAtFrame(f)


def hc_matrix(f):
    return hou.node(HC).worldTransformAtTime(hou.frameToTime(f))


def key_curve(parm, f):
    """Raw keyed (Hermite/bezier) value of a channel, ignoring the layer part of its segment expression."""
    ks = parm.keyframes()
    if f <= ks[0].frame():
        return ks[0].value()
    if f >= ks[-1].frame():
        return ks[-1].value()
    a = b = None
    for i in range(len(ks) - 1):
        a, b = ks[i], ks[i + 1]
        if a.frame() <= f <= b.frame():
            break
    dt = b.time() - a.time()
    u = (hou.frameToTime(f) - a.time()) / dt
    m0 = a.slope() * dt
    m1 = b.inSlope() * dt
    return ((2 * u ** 3 - 3 * u ** 2 + 1) * a.value() + (u ** 3 - 2 * u ** 2 + u) * m0 +
            (-2 * u ** 3 + 3 * u ** 2) * b.value() + (u ** 3 - u ** 2) * m1)


def keyed_local(f):
    n = hou.node(CB)
    return hou.Vector3(key_curve(n.parm('tx'), f), key_curve(n.parm('ty'), f), key_curve(n.parm('tz'), f))


def bob(f):
    t = hou.frameToTime(f)
    a = _ev('bob_amp', f) * _ev('bob_w', f)
    by = a * (math.sin(2 * math.pi * BOB_F1 * t) + 0.5 * math.sin(2 * math.pi * BOB_F2 * t + 1.0)) / 1.5
    bx = 0.35 * a * math.sin(2 * math.pi * BOB_FX * t + 0.4)
    return hou.Vector3(bx, by, 0.0)


def w_hand(f):
    return min(1.0, max(0.0, _ev('w_hand', f)))


def place(k, f):
    """Map a hand_contact-space point to world: blend of frozen reference frame and live hand_contact."""
    w = w_hand(f)
    ref = k * hc_matrix(REF_F)
    if w <= 0.0:
        return ref
    live = k * hc_matrix(f)
    return ref * (1.0 - w) + live * w


def bf_pos(f=None):
    if f is None:
        f = hou.frame()
    return place(keyed_local(f), f) + bob(f)


def bf_delta(axis, f=None):
    """Layer offset added to bezier() in the CTRL_body t* key segments."""
    if f is None:
        f = hou.frame()
    k = keyed_local(f)
    return (place(k, f) + bob(f))[axis] - k[axis]


def to_local(world_pt):
    return hou.Vector3(world_pt) * hc_matrix(REF_F).inverted()

